BEGIN;

ALTER TABLE slack_channels DROP CONSTRAINT IF EXISTS slack_channels_purpose_check;

DO $$ BEGIN
  ALTER TABLE slack_channels ADD CONSTRAINT slack_channels_purpose_check CHECK (purpose IN ('approvals','admin','operations','finance','it','training','security','custom'));
EXCEPTION WHEN duplicate_object THEN NULL; WHEN duplicate_table THEN NULL;
END $$;

COMMIT;

