-- Migration 053: A2P/TCPA SMS consent tracking.
--
-- Current consent state lives on users; every grant/revoke is ALSO appended
-- to sms_consent_events so historical consent is never overwritten and the
-- full trail is auditable (10DLC / toll-free / short-code / CTIA / TCPA).
ALTER TABLE users ADD COLUMN IF NOT EXISTS sms_consent BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE users ADD COLUMN IF NOT EXISTS sms_consent_at TIMESTAMPTZ;
ALTER TABLE users ADD COLUMN IF NOT EXISTS sms_consent_ip TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS sms_consent_user_agent TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS sms_consent_version TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS sms_consent_source TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS sms_consent_revoked_at TIMESTAMPTZ;

CREATE TABLE IF NOT EXISTS sms_consent_events (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  action TEXT NOT NULL CHECK (action IN ('granted', 'revoked')),
  source TEXT NOT NULL,          -- onboarding | customer_settings | cleaner_settings | sms_start | sms_stop | admin
  consent_version TEXT,          -- policy version in force at the time (e.g. 'v1')
  ip_address TEXT,
  user_agent TEXT,
  phone TEXT,                    -- number the consent applies to, when known
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_sms_consent_events_user ON sms_consent_events(user_id, created_at DESC);

-- ─────────────────────────────────────────────────────────────────────────
-- 054_strict_rls.sql
-- ─────────────────────────────────────────────────────────────────────────
/*
 * Copyright © 2026–Present ClearKey Solutions, LLC.
 * All Rights Reserved.
 *
 * Proprietary and Confidential.
 */

-- Migration 054: Strict row-level security (deny-by-default).
--
-- Architecture note: the Sweepr API (Cloudflare Worker) connects to Neon as
-- the database OWNER, which bypasses RLS (we intentionally do not FORCE RLS),
-- so nothing about the app changes. Integration partners (Stripe, Clerk,
-- Checkr, Didit, MailerSend, Slack, Mapbox, PostHog) never connect to
-- Postgres directly — they talk to the API over HTTPS — so they are
-- unaffected by design.
--
-- What changes: migration 026 enabled RLS on 7 tables but added a permissive
-- `app_full_access` policy with no TO clause, which applies to PUBLIC — i.e.
-- ANY role with a table grant could read every row. This migration:
--   1. Drops those overly-permissive policies (the owner doesn't need them).
--   2. Enables RLS on EVERY table in public, so any non-owner role
--      (read-only analytics, a leaked credential, an accidental anon grant)
--      sees zero rows unless a scoped policy is explicitly created for it.
--   3. Revokes all table/sequence privileges from PUBLIC, closing the
--      default-grant path entirely.
DO $$
DECLARE
  t RECORD;
BEGIN
  FOR t IN
    SELECT tablename FROM pg_tables WHERE schemaname = 'public'
  LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t.tablename);
    -- Remove the PUBLIC-scoped permissive policy from migration 026 if present.
    IF EXISTS (
      SELECT 1 FROM pg_policies
      WHERE schemaname = 'public' AND tablename = t.tablename
        AND policyname = 'app_full_access'
    ) THEN
      EXECUTE format('DROP POLICY app_full_access ON public.%I', t.tablename);
    END IF;
  END LOOP;
END $$;

-- Close the default-privilege path for any role that isn't explicitly granted.
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM PUBLIC;
ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON TABLES FROM PUBLIC;
ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON SEQUENCES FROM PUBLIC;

