-- 084_yardstik_webhook_dedup.sql
-- ─────────────────────────────────────────────────────────────────────────
/*
 * Copyright © 2026–Present ClearKey Solutions, LLC.
 * All Rights Reserved.
 *
 * Proprietary and Confidential.
 */

-- 084_yardstik_webhook_dedup.sql
-- Idempotency / replay protection for inbound Yardstik webhooks.
--
-- Yardstik does not sign a timestamp we can use for a freshness window, so a
-- captured (still-validly-signed) webhook could be replayed to re-drive a
-- cleaner's background-check status transition. We dedup on a stable event key
-- (the webhook body's `id` when present, else a SHA-256 hash of the raw body +
-- signature) the same way stripe_events dedups Stripe deliveries: the row is
-- claimed with INSERT … ON CONFLICT DO NOTHING RETURNING, and a delivery that
-- fails to claim a row is treated as a duplicate and skipped.

CREATE TABLE IF NOT EXISTS yardstik_webhook_events (
  id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  event_key    TEXT UNIQUE NOT NULL,
  event        TEXT,
  resource_id  TEXT,
  received_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_yardstik_webhook_events_received
  ON yardstik_webhook_events(received_at);

-- ─────────────────────────────────────────────────────────────────────────
-- 085_founding_and_promotions.sql
-- ─────────────────────────────────────────────────────────────────────────
-- Copyright © 2026–Present ClearKey Solutions, LLC. All Rights Reserved.
-- Proprietary and Confidential.

-- ============================================================================
-- Founding Member Program + Promotions Engine
-- ============================================================================
-- Two related feature sets:
--   1) Founding Member status for cleaners AND customers — a permanent,
--      one-time designation with a sequential founder number, lifetime perks
--      (5% cleaner earnings bonus), and revoke/restore controls.
--   2) A promotions engine whose "founding member" templates are the funnel
--      that grants that status. Promotions are self-contained rows (design +
--      CTA + display + expiry as JSONB) addressable by a public slug URL.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1) Founding Member columns — cleaners
-- ---------------------------------------------------------------------------
ALTER TABLE cleaners
  ADD COLUMN IF NOT EXISTS founding_member                BOOLEAN     NOT NULL DEFAULT FALSE,
  ADD COLUMN IF NOT EXISTS founding_member_id             INTEGER,      -- sequential founder #
  ADD COLUMN IF NOT EXISTS founding_member_since          TIMESTAMPTZ,  -- never changes once set
  ADD COLUMN IF NOT EXISTS founding_member_revoked        BOOLEAN     NOT NULL DEFAULT FALSE,
  ADD COLUMN IF NOT EXISTS founding_member_revoked_reason TEXT,
  ADD COLUMN IF NOT EXISTS founding_member_revoked_at     TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS founding_welcome_seen          BOOLEAN     NOT NULL DEFAULT FALSE;

-- ---------------------------------------------------------------------------
-- 2) Founding Member columns — customers (mirror perks/recognition)
-- ---------------------------------------------------------------------------
ALTER TABLE customers
  ADD COLUMN IF NOT EXISTS founding_member                BOOLEAN     NOT NULL DEFAULT FALSE,
  ADD COLUMN IF NOT EXISTS founding_member_id             INTEGER,
  ADD COLUMN IF NOT EXISTS founding_member_since          TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS founding_member_revoked        BOOLEAN     NOT NULL DEFAULT FALSE,
  ADD COLUMN IF NOT EXISTS founding_member_revoked_reason TEXT,
  ADD COLUMN IF NOT EXISTS founding_member_revoked_at     TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS founding_welcome_seen          BOOLEAN     NOT NULL DEFAULT FALSE;

-- Sequential founder numbers. Separate sequences per audience so cleaners and
-- customers each read "Founding Member #1, #2, …" from their own count.
CREATE SEQUENCE IF NOT EXISTS founding_member_cleaner_seq  START 1;
CREATE SEQUENCE IF NOT EXISTS founding_member_customer_seq START 1;

-- Founder numbers are unique within an audience (partial — ignore NULLs / non-members).
CREATE UNIQUE INDEX IF NOT EXISTS idx_cleaners_founding_id
  ON cleaners (founding_member_id) WHERE founding_member_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_customers_founding_id
  ON customers (founding_member_id) WHERE founding_member_id IS NOT NULL;
-- Search/tiebreaker + directory queries filter on active membership.
CREATE INDEX IF NOT EXISTS idx_cleaners_founding_active
  ON cleaners (founding_member) WHERE founding_member = TRUE AND founding_member_revoked = FALSE;

-- ---------------------------------------------------------------------------
-- 3) Promotions engine
-- ---------------------------------------------------------------------------
-- One promotion = one page of designed content (PowerPoint-style single slide),
-- a templated CTA, display rules, and expiry. Everything the widget needs to
-- render + behave lives on the row, so adding a promo needs zero extra config.
CREATE TABLE IF NOT EXISTS promotions (
  id                     UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  slug                   TEXT UNIQUE NOT NULL,               -- public URL: /promo/:slug
  name                   TEXT NOT NULL,                      -- admin-facing label
  template_key           TEXT,                               -- catalog template it was built from
  audience               TEXT NOT NULL DEFAULT 'all'
                         CHECK (audience IN ('all', 'visitors', 'customers', 'cleaners')),
  status                 TEXT NOT NULL DEFAULT 'draft'
                         CHECK (status IN ('draft', 'active', 'paused', 'expired', 'archived')),

  -- Rich single-page design: ordered blocks (heading/text/image/spacer/badge…)
  -- plus canvas styling (background, theme). Rendered by the shared PromoWidget.
  design                 JSONB NOT NULL DEFAULT '{}'::jsonb,

  -- Templated CTA: { label, action: 'claim'|'link'|'dismiss', url?,
  --                  requireField?: 'email'|'phone'|'none', successMessage? }
  cta                    JSONB NOT NULL DEFAULT '{}'::jsonb,

  -- Display rules: { placement: 'modal'|'banner'|'inline', pages: [..],
  --                  delaySeconds, persist: bool, frequency: 'once'|'every_visit'|'daily',
  --                  showOnFirstVisit: bool }
  display                JSONB NOT NULL DEFAULT '{}'::jsonb,

  -- Expiry — either can fire; whichever hits first expires the promo.
  starts_at              TIMESTAMPTZ,
  expires_at             TIMESTAMPTZ,                        -- time-based expiry
  max_claims             INTEGER,                            -- claim-count expiry (NULL = unlimited)
  claim_count            INTEGER NOT NULL DEFAULT 0,
  view_count             INTEGER NOT NULL DEFAULT 0,

  -- When claimed, confer Founding Member status on the claimant.
  grants_founding_member BOOLEAN NOT NULL DEFAULT FALSE,

  created_by             TEXT,
  created_at             TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at             TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_promotions_active
  ON promotions (status) WHERE status = 'active';
CREATE INDEX IF NOT EXISTS idx_promotions_slug ON promotions (slug);

-- One row per claim. Dedupe by (promotion, email) and (promotion, user) so the
-- same person can't inflate claim_count or double-grant founding status.
CREATE TABLE IF NOT EXISTS promotion_claims (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  promotion_id  UUID NOT NULL REFERENCES promotions(id) ON DELETE CASCADE,
  user_id       UUID REFERENCES users(id) ON DELETE SET NULL,
  email         TEXT,
  phone         TEXT,
  field_value   TEXT,                                       -- raw captured CTA field
  granted_founding BOOLEAN NOT NULL DEFAULT FALSE,
  ip            TEXT,
  meta          JSONB NOT NULL DEFAULT '{}'::jsonb,
  claimed_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_promo_claims_promo ON promotion_claims (promotion_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_promo_claims_email
  ON promotion_claims (promotion_id, LOWER(email)) WHERE email IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_promo_claims_user
  ON promotion_claims (promotion_id, user_id) WHERE user_id IS NOT NULL;

ALTER TABLE promotions       ENABLE ROW LEVEL SECURITY;
ALTER TABLE promotion_claims ENABLE ROW LEVEL SECURITY;

-- ---------------------------------------------------------------------------
-- 4) Founding Member program settings (site_settings key/value bag)
-- ---------------------------------------------------------------------------
INSERT INTO site_settings (key, value) VALUES
  ('founding.cleaner_enrollment_open',  'true'),
  ('founding.customer_enrollment_open', 'true'),
  ('founding.cleaner_cutoff_at',        ''),      -- ISO date; empty = no time cutoff
  ('founding.customer_cutoff_at',       ''),
  ('founding.cleaner_max_members',      ''),      -- integer; empty = no count cutoff
  ('founding.customer_max_members',     ''),
  ('founding.earnings_bonus_pct',       '5'),     -- cleaner lifetime payout bonus
  ('founding.since_label',              '2026')   -- "Founding Member since 2026"
ON CONFLICT (key) DO NOTHING;

-- ─────────────────────────────────────────────────────────────────────────
-- 086_founder_badge_color.sql
-- ─────────────────────────────────────────────────────────────────────────
-- Copyright © 2026–Present ClearKey Solutions, LLC. All Rights Reserved.
-- Proprietary and Confidential.

-- Founding Member badge color. Each founder picks ONE of five colorways when
-- they claim their status (carbon-gold, rose-gold, classic-gold, seafoam-gold,
-- minimal-gold). The choice is permanent — locked_at records the moment it was
-- made and the API refuses any change after that. The badge artwork carries the
-- founder's first-name initial, which is INFERRED from first_name server-side
-- (never chosen), so only the color is stored.
ALTER TABLE cleaners
  ADD COLUMN IF NOT EXISTS founding_badge_color     TEXT,
  ADD COLUMN IF NOT EXISTS founding_badge_locked_at TIMESTAMPTZ;

ALTER TABLE customers
  ADD COLUMN IF NOT EXISTS founding_badge_color     TEXT,
  ADD COLUMN IF NOT EXISTS founding_badge_locked_at TIMESTAMPTZ;

-- ─────────────────────────────────────────────────────────────────────────
-- 087_coupons_engine.sql
-- ─────────────────────────────────────────────────────────────────────────
-- Copyright © 2026–Present ClearKey Solutions, LLC. All Rights Reserved.
-- Proprietary and Confidential.

-- ============================================================================
-- Coupons engine + promo rewards + milestones
-- ============================================================================
-- Coupons are the actual perks (promos are the customer-facing vehicles).
-- They are SILENT: no widget — they sit on the person's account and apply
-- automatically to the next qualifying booking. Sign-up is required to hold
-- one (pre-signup claims bind to an email and attach at first sign-in), and
-- they default to 180-day validity (see legal Promotions & Coupons Terms).
-- ============================================================================

CREATE TABLE IF NOT EXISTS coupons (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  code          TEXT UNIQUE NOT NULL,          -- display code, e.g. SWPR-7K4QXH
  title         TEXT NOT NULL,                 -- "15% off your next booking"
  description   TEXT,
  theme         TEXT,                          -- valentines | christmas | … (display only)
  kind          TEXT NOT NULL CHECK (kind IN ('percent_off', 'amount_off', 'free_addon')),
  value         INTEGER NOT NULL DEFAULT 0,    -- percent (1-100) or cents; 0 for free_addon
  addon_key     TEXT,                          -- for kind=free_addon
  -- Ownership: user_id once signed up; email-only until then (attached on sign-in).
  user_id       UUID REFERENCES users(id) ON DELETE CASCADE,
  email         TEXT,
  source        TEXT NOT NULL DEFAULT 'admin', -- promo | milestone | theme | admin
  source_ref    TEXT,                          -- promo slug / milestone rule_key
  max_redemptions  INTEGER NOT NULL DEFAULT 1, -- one-time by default; >1 = multi-use
  redemption_count INTEGER NOT NULL DEFAULT 0,
  min_booking_total_cents INTEGER,             -- optional qualifying floor
  starts_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  expires_at    TIMESTAMPTZ NOT NULL DEFAULT NOW() + INTERVAL '180 days',
  status        TEXT NOT NULL DEFAULT 'active'
                CHECK (status IN ('active', 'exhausted', 'expired', 'revoked')),
  created_by    TEXT,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_coupons_user_active
  ON coupons (user_id) WHERE status = 'active';
CREATE INDEX IF NOT EXISTS idx_coupons_email_pending
  ON coupons (LOWER(email)) WHERE user_id IS NULL AND status = 'active';

-- One coupon per booking; a redemption is the audit record of the application.
CREATE TABLE IF NOT EXISTS coupon_redemptions (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  coupon_id     UUID NOT NULL REFERENCES coupons(id) ON DELETE CASCADE,
  booking_id    UUID UNIQUE NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,
  user_id       UUID REFERENCES users(id) ON DELETE SET NULL,
  amount_applied_cents INTEGER NOT NULL DEFAULT 0,
  addon_key     TEXT,
  redeemed_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Milestones: "100th customer", "150th completed clean", "2 years as a cleaner"…
-- Each rule carries a coupon template (JSONB) minted for the subject when hit.
CREATE TABLE IF NOT EXISTS milestone_rules (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  rule_key    TEXT UNIQUE NOT NULL,
  label       TEXT NOT NULL,
  kind        TEXT NOT NULL CHECK (kind IN (
                'nth_customer', 'nth_cleaner', 'nth_completed_booking',
                'cleaner_anniversary_years', 'customer_anniversary_years')),
  threshold   INTEGER NOT NULL,                -- N (count) or years
  coupon      JSONB NOT NULL DEFAULT '{}'::jsonb, -- template: kind/value/addonKey/title/theme/validDays/maxRedemptions
  active      BOOLEAN NOT NULL DEFAULT TRUE,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Dedup ledger: a rule fires at most once per subject.
CREATE TABLE IF NOT EXISTS milestone_awards (
  id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  rule_key     TEXT NOT NULL,
  subject_type TEXT NOT NULL,                  -- customer | cleaner | booking
  subject_id   UUID NOT NULL,
  coupon_id    UUID REFERENCES coupons(id) ON DELETE SET NULL,
  awarded_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (rule_key, subject_id)
);

-- Promotions gain a reward payload: what claiming actually GRANTS
-- (e.g. { coupon: { kind, value, addonKey, title, validDays, maxRedemptions,
--   minBookingTotalCents, offerMinutes } }). Founding grants stay on their own column.
ALTER TABLE promotions ADD COLUMN IF NOT EXISTS reward JSONB NOT NULL DEFAULT '{}'::jsonb;

-- The price ledger's event_type CHECK (mig. 058) must admit coupon discounts.
ALTER TABLE booking_price_ledger DROP CONSTRAINT IF EXISTS booking_price_ledger_event_type_check;
DO $$ BEGIN
  ALTER TABLE booking_price_ledger ADD CONSTRAINT booking_price_ledger_event_type_check CHECK (event_type IN (
    'initial_quote', 'addon_purchase', 'level_surcharge', 'additional_attention_fee',
    'refusal_fee', 'admin_adjustment', 'tax_adjustment', 'coupon_discount'
  ));
EXCEPTION WHEN duplicate_object THEN NULL; WHEN duplicate_table THEN NULL;
END $$;

ALTER TABLE coupons            ENABLE ROW LEVEL SECURITY;
ALTER TABLE coupon_redemptions ENABLE ROW LEVEL SECURITY;
ALTER TABLE milestone_rules    ENABLE ROW LEVEL SECURITY;
ALTER TABLE milestone_awards   ENABLE ROW LEVEL SECURITY;

-- ─────────────────────────────────────────────────────────────────────────
-- 088_coupon_stacking_locks.sql
-- ─────────────────────────────────────────────────────────────────────────
-- Copyright © 2026–Present ClearKey Solutions, LLC. All Rights Reserved.
-- Proprietary and Confidential.

-- ============================================================================
-- Coupon stacking permissions + strict one-claim-per-identity locks
-- ============================================================================

-- Per-coupon stacking permissions:
--   stackable = FALSE → the coupon applies alone (default).
--   stackable = TRUE  → may combine with other stackable coupons on one booking.
--   max_stack         → cap on how many coupons total may participate in a stack
--                       this coupon is part of (NULL = no cap it imposes).
ALTER TABLE coupons
  ADD COLUMN IF NOT EXISTS stackable BOOLEAN NOT NULL DEFAULT FALSE,
  ADD COLUMN IF NOT EXISTS max_stack INTEGER;

-- Redemptions: a booking may now consume MULTIPLE coupons (a stack), but any
-- individual coupon still applies to a given booking at most once.
ALTER TABLE coupon_redemptions DROP CONSTRAINT IF EXISTS coupon_redemptions_booking_id_key;
CREATE UNIQUE INDEX IF NOT EXISTS idx_coupon_redemption_once
  ON coupon_redemptions (coupon_id, booking_id);

-- STRICT claim locks: one coupon per identity per promo/milestone, enforced at
-- the database (the promo-claims dedup is the first line; this closes every
-- other path). Applies to both signed-in (user_id) and email-bound claims.
CREATE UNIQUE INDEX IF NOT EXISTS idx_coupons_source_user_once
  ON coupons (source, source_ref, user_id)
  WHERE user_id IS NOT NULL AND source IN ('promo', 'milestone');
CREATE UNIQUE INDEX IF NOT EXISTS idx_coupons_source_email_once
  ON coupons (source, source_ref, LOWER(email))
  WHERE email IS NOT NULL AND source IN ('promo', 'milestone');

-- ─────────────────────────────────────────────────────────────────────────
-- 089_smart_entry_and_sweepr_plus.sql
-- ─────────────────────────────────────────────────────────────────────────
-- Copyright © 2026–Present ClearKey Solutions, LLC.
-- Proprietary & Confidential. Internal Use Only.
--
-- Sweepr Smart Entry + Sweepr+ membership.
--
-- Smart Entry gives an assigned, verified cleaner *temporary*, booking-specific
-- access to a customer's home. A working credential (door code / digital key /
-- unlock command) must NEVER be exposed merely because it exists or because a
-- cleaner is assigned — every reveal/unlock passes a fresh server-side
-- authorization decision (see lib/homeAccess.ts). Plaintext credentials are
-- never stored here; only envelope-encrypted references (see lib/crypto.ts).

-- ── Sweepr+ membership ────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS sweepr_plus_memberships (
  id                      UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  user_id                 UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  -- Stripe subscription lifecycle. Benefits are active only when Stripe reports
  -- the subscription active/trialing (never on a bare authorization).
  stripe_customer_id      TEXT,
  stripe_subscription_id  TEXT UNIQUE,
  stripe_price_id         TEXT,
  interval                TEXT CHECK (interval IN ('month','year')),
  status                  TEXT NOT NULL DEFAULT 'incomplete'
                            CHECK (status IN ('incomplete','trialing','active','past_due','canceled','incomplete_expired','unpaid')),
  cancel_at_period_end    BOOLEAN NOT NULL DEFAULT FALSE,
  current_period_end      TIMESTAMPTZ,
  grace_until             TIMESTAMPTZ,           -- past_due grace window
  -- Rolling benefit accounting.
  discount_cents_this_month INTEGER NOT NULL DEFAULT 0,
  discount_month_key      TEXT,                  -- 'YYYY-MM' the counter belongs to
  last_reschedule_waived_at TIMESTAMPTZ,         -- one waiver / 90 days
  created_at              TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at              TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
-- One live membership row per user (historical canceled rows allowed).
CREATE UNIQUE INDEX IF NOT EXISTS idx_sweepr_plus_active_user
  ON sweepr_plus_memberships (user_id)
  WHERE status IN ('trialing','active','past_due');

-- A membership is "benefit-eligible" when active/trialing, or past_due within
-- its grace window. Server code is the source of truth; this is a convenience.

-- ── Smart-lock connections & devices (per spec §16) ──────────────────────────
CREATE TABLE IF NOT EXISTS smart_lock_connections (
  id                          UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  customer_id                 UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  property_id                 UUID REFERENCES addresses(id) ON DELETE SET NULL,
  provider                    TEXT NOT NULL DEFAULT 'seam',
  provider_account_reference  TEXT,              -- e.g. Seam connected_account id
  encrypted_provider_token_reference TEXT,       -- vault/secret pointer, never a raw token
  status                      TEXT NOT NULL DEFAULT 'pending'
                                CHECK (status IN ('pending','connected','revoked','error')),
  connected_at                TIMESTAMPTZ,
  revoked_at                  TIMESTAMPTZ,
  last_health_check_at        TIMESTAMPTZ,
  created_at                  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at                  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_smart_lock_conn_customer ON smart_lock_connections (customer_id);

CREATE TABLE IF NOT EXISTS smart_lock_devices (
  id                        UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  connection_id             UUID NOT NULL REFERENCES smart_lock_connections(id) ON DELETE CASCADE,
  property_id               UUID REFERENCES addresses(id) ON DELETE SET NULL,
  provider_device_reference TEXT NOT NULL,
  display_name              TEXT,
  device_type               TEXT,
  supports_remote_unlock    BOOLEAN NOT NULL DEFAULT FALSE,
  supports_remote_lock      BOOLEAN NOT NULL DEFAULT FALSE,
  supports_temporary_codes  BOOLEAN NOT NULL DEFAULT FALSE,
  supports_scheduled_codes  BOOLEAN NOT NULL DEFAULT FALSE,
  supports_lock_status      BOOLEAN NOT NULL DEFAULT FALSE,
  status                    TEXT NOT NULL DEFAULT 'active'
                              CHECK (status IN ('active','offline','removed')),
  created_at                TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at                TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_smart_lock_device_conn ON smart_lock_devices (connection_id);

-- ── Per-booking access authorization + credentials ───────────────────────────
CREATE TABLE IF NOT EXISTS booking_access_authorizations (
  id                    UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  booking_id            UUID NOT NULL UNIQUE REFERENCES bookings(id) ON DELETE CASCADE,
  customer_id           UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  property_id           UUID REFERENCES addresses(id) ON DELETE SET NULL,
  lock_device_id        UUID REFERENCES smart_lock_devices(id) ON DELETE SET NULL,
  -- Selected access method for the booking (spec §6).
  access_method         TEXT NOT NULL DEFAULT 'home'
                          CHECK (access_method IN ('home','keypad_code','smart_entry','lockbox','front_desk','other')),
  access_starts_at      TIMESTAMPTZ,
  access_ends_at        TIMESTAMPTZ,
  geofence_radius_meters INTEGER NOT NULL DEFAULT 150,
  -- Explicit, versioned consent (spec §7).
  customer_authorized_at TIMESTAMPTZ,
  consent_version       TEXT,
  consent_ip            TEXT,
  consent_session_id    TEXT,
  revoked_at            TIMESTAMPTZ,
  revocation_reason     TEXT,
  created_at            TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at            TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS booking_access_credentials (
  id                            UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  authorization_id              UUID NOT NULL REFERENCES booking_access_authorizations(id) ON DELETE CASCADE,
  credential_type               TEXT NOT NULL
                                  CHECK (credential_type IN ('customer_pin','generated_pin','remote_unlock','digital_key','instructions')),
  -- Envelope-encrypted; PLAINTEXT MUST NEVER BE STORED HERE.
  encrypted_credential          TEXT,
  provider_credential_reference TEXT,           -- e.g. Seam access_code id
  credential_status             TEXT NOT NULL DEFAULT 'pending'
                                  CHECK (credential_status IN ('pending','active','expired','revoked','destroyed')),
  activates_at                  TIMESTAMPTZ,
  expires_at                    TIMESTAMPTZ,
  last_revealed_at              TIMESTAMPTZ,
  reveal_count                  INTEGER NOT NULL DEFAULT 0,
  destroyed_at                  TIMESTAMPTZ,
  created_at                    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at                    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_bac_credentials_auth ON booking_access_credentials (authorization_id);

-- ── Immutable access-event log (spec §16) ────────────────────────────────────
CREATE TABLE IF NOT EXISTS home_access_events (
  id                        UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  booking_id                UUID REFERENCES bookings(id) ON DELETE SET NULL,
  customer_id               UUID REFERENCES users(id) ON DELETE SET NULL,
  cleaner_id                UUID REFERENCES users(id) ON DELETE SET NULL,
  property_id               UUID REFERENCES addresses(id) ON DELETE SET NULL,
  device_id                 UUID REFERENCES smart_lock_devices(id) ON DELETE SET NULL,
  event_type                TEXT NOT NULL,       -- reveal_requested, unlock_requested, unlocked, locked, denied, revoked, code_created …
  decision                  TEXT,                -- allowed | denied
  denial_reason             TEXT,
  provider_event_reference  TEXT,
  location_distance_meters  DOUBLE PRECISION,
  location_accuracy_meters  DOUBLE PRECISION,
  session_id                TEXT,
  ip_address                TEXT,
  device_reference          TEXT,
  occurred_at               TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  metadata                  JSONB               -- sanitized: NEVER a credential or provider secret
);
CREATE INDEX IF NOT EXISTS idx_home_access_events_booking ON home_access_events (booking_id);
CREATE INDEX IF NOT EXISTS idx_home_access_events_cleaner ON home_access_events (cleaner_id, occurred_at DESC);

-- ── Booking columns for the selected access method + Smart Entry billing ──────
ALTER TABLE bookings ADD COLUMN IF NOT EXISTS access_method TEXT;
ALTER TABLE bookings ADD COLUMN IF NOT EXISTS smart_entry_fee_cents INTEGER NOT NULL DEFAULT 0;
ALTER TABLE bookings ADD COLUMN IF NOT EXISTS sweepr_plus_discount_cents INTEGER NOT NULL DEFAULT 0;

-- ── Price-ledger: admit Smart Entry fee + Sweepr+ discount ───────────────────
ALTER TABLE booking_price_ledger DROP CONSTRAINT IF EXISTS booking_price_ledger_event_type_check;
DO $$ BEGIN
  ALTER TABLE booking_price_ledger ADD CONSTRAINT booking_price_ledger_event_type_check CHECK (event_type IN (
    'initial_quote', 'addon_purchase', 'level_surcharge', 'additional_attention_fee',
    'refusal_fee', 'admin_adjustment', 'tax_adjustment', 'coupon_discount',
    'smart_entry_fee', 'membership_discount'
  ));
EXCEPTION WHEN duplicate_object THEN NULL; WHEN duplicate_table THEN NULL;
END $$;

-- ── RLS parity with the rest of the schema ───────────────────────────────────
ALTER TABLE sweepr_plus_memberships        ENABLE ROW LEVEL SECURITY;
ALTER TABLE smart_lock_connections         ENABLE ROW LEVEL SECURITY;
ALTER TABLE smart_lock_devices             ENABLE ROW LEVEL SECURITY;
ALTER TABLE booking_access_authorizations  ENABLE ROW LEVEL SECURITY;
ALTER TABLE booking_access_credentials     ENABLE ROW LEVEL SECURITY;
ALTER TABLE home_access_events             ENABLE ROW LEVEL SECURITY;

-- ─────────────────────────────────────────────────────────────────────────
-- 090_platform_identity_workspaces.sql
-- ─────────────────────────────────────────────────────────────────────────
-- Copyright © 2026–Present ClearKey Solutions, LLC.
-- Proprietary & Confidential. Internal Use Only.
--
-- Platform identity + workspace model (multi-app auth architecture).
--
-- Sweepr runs four separate Clerk applications (customer, business, cleaner,
-- admin), each an isolated auth silo with its own user pool. This migration
-- adds the Sweepr-owned layer that connects them:
--
--   Clerk authenticates access to ONE app;
--   Sweepr identifies the person, organizations, workspaces, memberships,
--   and permissions ACROSS the platform.
--
-- Three concepts, never collapsed:
--   auth identity     — a user inside one Clerk application
--   platform person   — the canonical human
--   membership        — what that person can do inside a workspace
--
-- Everything here is ADDITIVE. The legacy `users` table remains the join point
-- for all existing FKs; platform_people/auth_identities wrap it so current
-- code keeps working while new boundaries adopt the richer model.

-- ── Canonical person ─────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS platform_people (
  id               UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  -- Bridge to the legacy fused record; one person per users row initially.
  user_id          UUID UNIQUE REFERENCES users(id) ON DELETE SET NULL,
  first_name       TEXT,
  last_name        TEXT,
  display_name     TEXT,
  canonical_email  TEXT,
  canonical_phone  TEXT,
  avatar_url       TEXT,
  locale           TEXT,
  timezone         TEXT,
  status           TEXT NOT NULL DEFAULT 'active'
                     CHECK (status IN ('active','suspended','deleted')),
  created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at       TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_platform_people_email ON platform_people (LOWER(canonical_email));

-- ── App-scoped authentication identities ─────────────────────────────────────
-- One row per (Clerk application, Clerk user). The same person may hold several
-- (customer + business + cleaner); admin identities are NEVER auto-linked by
-- email — linking requires explicit provisioning (see lib/identity.ts).
CREATE TABLE IF NOT EXISTS auth_identities (
  id                    UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  platform_person_id    UUID NOT NULL REFERENCES platform_people(id) ON DELETE CASCADE,
  auth_provider         TEXT NOT NULL DEFAULT 'clerk',
  auth_application      TEXT NOT NULL
                          CHECK (auth_application IN ('customer','business','cleaner','admin')),
  provider_user_id      TEXT NOT NULL,
  primary_email         TEXT,
  primary_phone         TEXT,
  email_verified        BOOLEAN NOT NULL DEFAULT FALSE,
  phone_verified        BOOLEAN NOT NULL DEFAULT FALSE,
  status                TEXT NOT NULL DEFAULT 'active'
                          CHECK (status IN ('active','suspended','deleted')),
  last_authenticated_at TIMESTAMPTZ,
  created_at            TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at            TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (auth_application, provider_user_id)
);
CREATE INDEX IF NOT EXISTS idx_auth_identities_person ON auth_identities (platform_person_id);
CREATE INDEX IF NOT EXISTS idx_auth_identities_email ON auth_identities (auth_application, LOWER(primary_email));

-- ── Optional legal/operational parent entity ─────────────────────────────────
CREATE TABLE IF NOT EXISTS platform_organizations (
  id                    UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  display_name          TEXT NOT NULL,
  legal_name            TEXT,
  tax_profile_reference TEXT,
  status                TEXT NOT NULL DEFAULT 'active'
                          CHECK (status IN ('active','suspended','closed')),
  created_at            TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at            TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ── Workspaces ────────────────────────────────────────────────────────────────
-- personal_customer: the implicit workspace every customer already has.
-- business_customer: managed only through the Business app.
-- cleaner_business:  managed only through the Cleaner app.
CREATE TABLE IF NOT EXISTS workspaces (
  id                             UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  platform_organization_id       UUID REFERENCES platform_organizations(id) ON DELETE SET NULL,
  workspace_category             TEXT NOT NULL
                                   CHECK (workspace_category IN ('personal_customer','business_customer','cleaner_business')),
  name                           TEXT NOT NULL,
  legal_name                     TEXT,
  slug                           TEXT UNIQUE,
  logo_url                       TEXT,
  business_type                  TEXT,
  status                         TEXT NOT NULL DEFAULT 'active'
                                   CHECK (status IN ('active','pending_identity_claim','suspended','archived','closed')),
  created_by_platform_person_id  UUID REFERENCES platform_people(id) ON DELETE SET NULL,
  timezone                       TEXT,
  locale                         TEXT,
  created_at                     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at                     TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_workspaces_category ON workspaces (workspace_category, status);

-- ── Roles (Sweepr-owned; Clerk org roles are only coarse session hints) ──────
-- Permissions are a TEXT[] of permission keys; the catalog lives in
-- lib/rbac.ts so new keys don't need migrations. System roles are seeded per
-- category and are not deletable by workspaces.
CREATE TABLE IF NOT EXISTS workspace_roles (
  id                 UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  workspace_category TEXT NOT NULL
                       CHECK (workspace_category IN ('personal_customer','business_customer','cleaner_business')),
  key                TEXT NOT NULL,
  label              TEXT NOT NULL,
  description        TEXT,
  permissions        TEXT[] NOT NULL DEFAULT '{}',
  is_system          BOOLEAN NOT NULL DEFAULT TRUE,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (workspace_category, key)
);

-- Business Customer roles (spec §14)
INSERT INTO workspace_roles (workspace_category, key, label, permissions) VALUES
  ('business_customer','owner','Owner',
   '{workspace.manage,workspace.close,workspace.transfer,members.manage,properties.manage,bookings.manage,billing.manage,reports.view,integrations.manage}'),
