-- Versioned archive of legal.getsweepr.com documents, stored as static
-- snapshots (document.html, document.pdf, metadata.json) in the sweepr-legal
-- R2 bucket under legal/<slug>/v<version>/ — separate from the general
-- objects/photos bucket. This row tracks which version is "current" per
-- slug and who published it; the live legal app keeps rendering from React
-- as today, this table is the archival/audit trail alongside it.
CREATE TABLE IF NOT EXISTS legal_document_versions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  slug TEXT NOT NULL,
  version TEXT NOT NULL,
  title TEXT NOT NULL,
  category TEXT NOT NULL,
  r2_prefix TEXT NOT NULL,
  is_current BOOLEAN NOT NULL DEFAULT TRUE,
  published_by_clerk_id TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (slug, version)
);

CREATE INDEX IF NOT EXISTS idx_legal_document_versions_slug_current
  ON legal_document_versions (slug, is_current);

-- ─────────────────────────────────────────────────────────────────────────
-- 095_legal_attorneys.sql
-- ─────────────────────────────────────────────────────────────────────────
-- Copyright © 2026–Present ClearKey Solutions, LLC.
-- All Rights Reserved.
--
-- Proprietary and Confidential.
--
-- Unauthorized copying, modification, disclosure,
-- distribution, reverse engineering, or use is prohibited.

-- External reviewing attorney(s): a small, isolated identity (NOT a staff
-- admin, NOT a customer/cleaner user) who can sign in via a signed magic
-- link to view, edit, and approve archived legal documents. Kept separate
-- from the staff admin Clerk app on purpose — this is one outside counsel,
-- not a platform operator.
CREATE TABLE IF NOT EXISTS legal_attorneys (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  email TEXT NOT NULL UNIQUE,
  full_name TEXT NOT NULL,
  bar_number TEXT,
  bar_state TEXT,
  firm_name TEXT,
  title TEXT,
  phone TEXT,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Single-use, expiring sign-in tokens (convention 8: sha256 token_hash +
-- expires_at + used_at IS NULL). The plaintext token only ever lives in the
-- magic link emailed to the attorney.
CREATE TABLE IF NOT EXISTS legal_attorney_login_tokens (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  attorney_id UUID NOT NULL REFERENCES legal_attorneys(id) ON DELETE CASCADE,
  token_hash TEXT NOT NULL UNIQUE,
  expires_at TIMESTAMPTZ NOT NULL,
  used_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_legal_attorney_login_tokens_hash
  ON legal_attorney_login_tokens (token_hash);

-- Attorney review/approval state stamped onto an archived document version.
ALTER TABLE legal_document_versions
  ADD COLUMN IF NOT EXISTS attorney_approved_by UUID REFERENCES legal_attorneys(id),
  ADD COLUMN IF NOT EXISTS attorney_approved_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS attorney_name TEXT,
  ADD COLUMN IF NOT EXISTS attorney_bar_number TEXT,
  ADD COLUMN IF NOT EXISTS edited_html_at TIMESTAMPTZ;

-- ─────────────────────────────────────────────────────────────────────────
-- 096_site_analytics.sql
-- ─────────────────────────────────────────────────────────────────────────
-- Copyright © 2026–Present ClearKey Solutions, LLC.
-- All Rights Reserved.
--
-- Proprietary and Confidential.
--
-- Unauthorized copying, modification, disclosure,
-- distribution, reverse engineering, or use is prohibited.

-- Site analytics (first-party, individualized) — DELIBERATELY separate from
-- the observability tables (analytics_events / api_request_logs), which track
-- product/API telemetry. These tables back the admin Site Analytics dashboard
-- and the /go/{code} tracking-link redirector served by the sweepr-analytics
-- worker (apps/analytics). Privacy posture: no raw IPs are ever stored — only
-- a salted SHA-256 hash — and geolocation is city-level (Cloudflare request
-- metadata), which keeps the store free of directly identifying data.

-- Admin-created short links: https://getsweepr.com/go/{code} → destination.
-- `source` is the acquisition channel (google, chatgpt, facebook, nextdoor…);
-- `campaign_id` is the optional coupon/ad-campaign discriminator.
CREATE TABLE IF NOT EXISTS tracking_links (
  id                  UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  code                TEXT        NOT NULL UNIQUE,
  label               TEXT        NOT NULL,
  source              TEXT        NOT NULL,
  campaign_id         TEXT,
  -- Path on getsweepr.com ("/pricing") or an absolute https URL on a
  -- *.getsweepr.com host. The worker validates again at redirect time so a
  -- corrupted row can never turn the redirector into an open redirect.
  destination         TEXT        NOT NULL DEFAULT '/',
  notes               TEXT,
  active              BOOLEAN     NOT NULL DEFAULT TRUE,
  -- Denormalized fast counters so the links table renders without scanning
  -- site_events; the event stream remains the source of truth for analysis.
  hit_count           BIGINT      NOT NULL DEFAULT 0,
  last_hit_at         TIMESTAMPTZ,
  created_by_clerk_id TEXT,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- One row per tracked interaction (pageview / click / link_hit / custom).
-- visitor_id + session_id are client-generated anonymous identifiers scoped
-- to *.getsweepr.com; they never contain account identity.
CREATE TABLE IF NOT EXISTS site_events (
  id           UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  occurred_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  app          TEXT        NOT NULL,
  event_type   TEXT        NOT NULL,
  visitor_id   TEXT        NOT NULL,
  session_id   TEXT        NOT NULL,
  path         TEXT,
  referrer     TEXT,
  -- Attribution at event time (first captured on landing, carried forward).
  source       TEXT,
  campaign_id  TEXT,
  link_code    TEXT,
  -- Click payload (event_type = 'click').
  click_target TEXT,
  click_href   TEXT,
  click_text   TEXT,
  -- Device (parsed server-side from the user agent at ingest).
  device_type  TEXT,
  browser      TEXT,
  browser_ver  TEXT,
  os           TEXT,
  os_ver       TEXT,
  screen_w     INT,
  screen_h     INT,
  viewport_w   INT,
  viewport_h   INT,
  language     TEXT,
  -- Geo from Cloudflare request metadata (city-level; lat/lon power the
  -- admin globe and are city centroids, not precise positions).
  country      TEXT,
  region       TEXT,
  city         TEXT,
  timezone     TEXT,
  latitude     REAL,
  longitude    REAL,
  asn_org      TEXT,
  -- Salted SHA-256 of the client IP (never the raw IP).
  ip_hash      TEXT,
  is_bot       BOOLEAN     NOT NULL DEFAULT FALSE,
  -- Optional IPinfo enrichment (privacy/VPN/company signals), present only
  -- when the worker has an IPINFO_TOKEN configured.
  ipinfo       JSONB,
  meta         JSONB       NOT NULL DEFAULT '{}'
);
CREATE INDEX IF NOT EXISTS idx_site_events_occurred ON site_events(occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_site_events_type     ON site_events(event_type, occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_site_events_session  ON site_events(session_id, occurred_at);
CREATE INDEX IF NOT EXISTS idx_site_events_visitor  ON site_events(visitor_id);
CREATE INDEX IF NOT EXISTS idx_site_events_link     ON site_events(link_code) WHERE link_code IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_site_events_path     ON site_events(path, occurred_at DESC);

-- One row per browsing session, upserted at ingest so the admin session
-- explorer and live-now views never scan the event stream. duration/bounce
-- are derived (last_seen_at - first_seen_at, pageviews = 1).
CREATE TABLE IF NOT EXISTS site_sessions (
  session_id    TEXT        PRIMARY KEY,
  visitor_id    TEXT        NOT NULL,
  first_seen_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  last_seen_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  app           TEXT,
  entry_path    TEXT,
  exit_path     TEXT,
  referrer      TEXT,
  source        TEXT,
  campaign_id   TEXT,
  link_code     TEXT,
  device_type   TEXT,
  browser       TEXT,
  os            TEXT,
  country       TEXT,
  region        TEXT,
  city          TEXT,
  latitude      REAL,
  longitude     REAL,
  is_bot        BOOLEAN     NOT NULL DEFAULT FALSE,
  pageviews     INT         NOT NULL DEFAULT 0,
  clicks        INT         NOT NULL DEFAULT 0,
  events        INT         NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_site_sessions_last    ON site_sessions(last_seen_at DESC);
CREATE INDEX IF NOT EXISTS idx_site_sessions_visitor ON site_sessions(visitor_id);
CREATE INDEX IF NOT EXISTS idx_site_sessions_source  ON site_sessions(source) WHERE source IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_site_sessions_link    ON site_sessions(link_code) WHERE link_code IS NOT NULL;

-- ─────────────────────────────────────────────────────────────────────────
-- 097_pricing_v2.sql
-- ─────────────────────────────────────────────────────────────────────────
-- Copyright © 2026–Present ClearKey Solutions, LLC.
-- All Rights Reserved.
--
-- Proprietary and Confidential.
--
-- Unauthorized copying, modification, disclosure,
-- distribution, reverse engineering, or use is prohibited.

-- Pricing v2: ONE authoritative, versioned quote service (labor-minutes
-- model with ordinal room-condition inference) replacing the five parallel
-- pricing formulas. See docs/PRICING_V2.md.
--
-- Rollout gate: the v2 engine only prices customer bookings once an admin
-- PUBLISHES a pricing version to Active for the booking's service area and
-- currency. Until then every existing path behaves exactly as before, so
-- deploying this migration changes no prices.
--
-- Money: integer cents. Durations: integer minutes. The full engine
-- configuration (labor matrix, clutter/size adjustments, extras, rates,
-- payout, scheduling, inference parameters) is snapshotted whole into
-- `config` JSONB per version — published versions are immutable (enforced
-- at the API layer; editing clones a new draft).

CREATE TABLE IF NOT EXISTS pricing_versions (
  id                     UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  name                   TEXT        NOT NULL,
  service_area           TEXT        NOT NULL DEFAULT 'default',
  currency               TEXT        NOT NULL DEFAULT 'USD',
  status                 TEXT        NOT NULL DEFAULT 'draft'
    CHECK (status IN ('draft', 'scheduled', 'active', 'superseded', 'archived')),
  -- Full engine configuration snapshot (shape: PricingConfigV2 in
  -- apps/api/src/lib/quoteEngine/types.ts).
  config                 JSONB       NOT NULL,
  -- Provenance of the inference parameters: cold_start | learned | blended.
  inference_provenance   TEXT        NOT NULL DEFAULT 'cold_start',
  source_version_id      UUID        REFERENCES pricing_versions(id) ON DELETE SET NULL,
  change_summary         TEXT,
  -- Result of the last server-side validation run ({ok, errors[], warnings[]}).
  validation             JSONB,
  effective_at           TIMESTAMPTZ,
  effective_end          TIMESTAMPTZ,
  created_by_clerk_id    TEXT,
  published_by_clerk_id  TEXT,
  published_at           TIMESTAMPTZ,
  created_at             TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at             TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
-- Exactly one Active version per (service_area, currency) at any instant.
CREATE UNIQUE INDEX IF NOT EXISTS idx_pricing_versions_one_active
  ON pricing_versions(service_area, currency) WHERE status = 'active';
CREATE INDEX IF NOT EXISTS idx_pricing_versions_status ON pricing_versions(status);
CREATE INDEX IF NOT EXISTS idx_pricing_versions_scheduled
  ON pricing_versions(effective_at) WHERE status = 'scheduled';

-- Immutable quote snapshots. Every v2 quote shown to a customer (or used at
-- checkout) is persisted here; bookings reference the exact snapshot so a
-- later pricing change can never rewrite what a customer accepted.
CREATE TABLE IF NOT EXISTS pricing_quotes_v2 (
  id                     UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  pricing_version_id     UUID        NOT NULL REFERENCES pricing_versions(id),
  -- Normalized input (rooms, conditions, clutter, counts-by-level overrides,
  -- sqft, extras, schedule, promo ids) and the complete engine result
  -- (components, inference breakdown, minutes, money, warnings).
  input                  JSONB       NOT NULL,
  result                 JSONB       NOT NULL,
  currency               TEXT        NOT NULL DEFAULT 'USD',
  total_cents            INT         NOT NULL,
  expected_labor_minutes INT         NOT NULL,
  scheduled_labor_minutes INT        NOT NULL,
  fingerprint            TEXT        NOT NULL,
  manual_review_required BOOLEAN     NOT NULL DEFAULT FALSE,
  customer_id            UUID        REFERENCES customers(id) ON DELETE SET NULL,
  consumed_by_booking_id UUID,
  created_at             TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  expires_at             TIMESTAMPTZ NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_pricing_quotes_v2_created ON pricing_quotes_v2(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_pricing_quotes_v2_customer ON pricing_quotes_v2(customer_id);

-- Append-only audit trail for the pricing workspace (draft edits, validation
-- runs, simulations, scheduling, publication, rollback clones, overrides).
-- Deliberately separate from admin_audit_log so pricing history is complete,
-- exportable, and cheap to query on its own.
CREATE TABLE IF NOT EXISTS pricing_audit_events (
  id               UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  version_id       UUID        REFERENCES pricing_versions(id) ON DELETE SET NULL,
  actor_clerk_id   TEXT,
  event            TEXT        NOT NULL,
  detail           JSONB       NOT NULL DEFAULT '{}',
  request_id       TEXT,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_pricing_audit_version ON pricing_audit_events(version_id, created_at);
CREATE INDEX IF NOT EXISTS idx_pricing_audit_created ON pricing_audit_events(created_at DESC);

-- Bookings carry immutable references to the exact version + quote snapshot
-- that priced them (v2 path only; legacy bookings leave these NULL).
ALTER TABLE bookings
  ADD COLUMN IF NOT EXISTS pricing_version_id UUID REFERENCES pricing_versions(id),
  ADD COLUMN IF NOT EXISTS pricing_quote_v2_id UUID REFERENCES pricing_quotes_v2(id);

