-- 101_team_cleans.sql
-- ─────────────────────────────────────────────────────────────────────────
/*
 * Copyright © 2026–Present ClearKey Solutions, LLC.
 * All Rights Reserved.
 *
 * Proprietary and Confidential.
 */

-- 101_team_cleans.sql
-- Team Cleans (multi-cleaner crews) — foundational schema.
--
-- A booking is no longer 1:1 with a cleaner. It has zero-or-more crew SEATS
-- (booking_crew_assignments): exactly one LEAD (seat_index 0) plus N MEMBER
-- seats. Solo bookings are the degenerate crew of one LEAD.
--
-- BACKWARD COMPATIBILITY (see docs/team-cleans-audit.md §13):
--   * bookings.cleaner_id is RETAINED as a compatibility pointer to the LEAD.
--     Every existing single-cleaner consumer keeps working unchanged.
--   * Every existing booking with a cleaner is backfilled as one LEAD seat.
--   * crew_status stays NULL on solo/legacy bookings, so nothing behaves
--     differently until the TEAM_CLEANS_ENABLED flag drives real crews.
-- The whole feature ships behind that flag (site_settings), default OFF.

-- ─── booking_crew_assignments: one row per crew seat ────────────────────────
CREATE TABLE IF NOT EXISTS booking_crew_assignments (
  id                        UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  booking_id                UUID NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,
  -- NULL while a seat is an open CANDIDATE (being staffed).
  cleaner_id                UUID REFERENCES cleaners(id),
  role                      TEXT NOT NULL CHECK (role IN ('LEAD', 'MEMBER')),
  -- 0 = LEAD, 1..N-1 = members. Stable seat identity for the booking.
  seat_index                INT  NOT NULL,
  status                    TEXT NOT NULL DEFAULT 'CANDIDATE'
    CHECK (status IN ('CANDIDATE', 'INVITED', 'ACCEPTED', 'DECLINED', 'EXPIRED',
                      'CANCELLED', 'REMOVED', 'NO_SHOW', 'COMPLETED')),

  -- This seat's share of the booking's expected labor (person-minutes).
  person_minutes            INT,
  assignment_score          DECIMAL(6, 2),
  score_breakdown           JSONB,
  -- Computed at payout from the cleaner payout pool × this seat's role share.
  earnings_cents            INT NOT NULL DEFAULT 0,

  offered_at                TIMESTAMPTZ,
  expires_at                TIMESTAMPTZ,
  responded_at              TIMESTAMPTZ,
  -- Mirrors the assignment_queue "free decline" mechanic.
  declined_free             BOOLEAN NOT NULL DEFAULT FALSE,

  check_in_at               TIMESTAMPTZ,
  check_out_at              TIMESTAMPTZ,
  -- A MEMBER who cannot GPS-verify may be vouched in on-site by an already
  -- arrived crew member via a short-lived PIN. Points at that voucher's seat.
  vouched_by_assignment_id  UUID REFERENCES booking_crew_assignments(id) ON DELETE SET NULL,

  -- Per-member Stripe transfer (the booking-level payouts row stays the pool).
  stripe_transfer_id        TEXT,
  -- Optimistic-concurrency / re-staffing generation for this seat.
  crew_assignment_version   INT NOT NULL DEFAULT 1,

  created_at                TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at                TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  UNIQUE (booking_id, seat_index)
);

-- A person holds at most one seat per booking (partial: open seats are NULL).
CREATE UNIQUE INDEX IF NOT EXISTS idx_bca_booking_cleaner_unique
  ON booking_crew_assignments (booking_id, cleaner_id)
  WHERE cleaner_id IS NOT NULL;
-- At most one LEAD seat per booking.
CREATE UNIQUE INDEX IF NOT EXISTS idx_bca_one_lead_per_booking
  ON booking_crew_assignments (booking_id)
  WHERE role = 'LEAD';

CREATE INDEX IF NOT EXISTS idx_bca_booking_status ON booking_crew_assignments (booking_id, status);
CREATE INDEX IF NOT EXISTS idx_bca_cleaner_status ON booking_crew_assignments (cleaner_id, status)
  WHERE cleaner_id IS NOT NULL;

COMMENT ON TABLE booking_crew_assignments IS
  'One row per crew seat on a booking (LEAD seat_index 0 + N MEMBER seats). Source of truth for who is assigned; bookings.cleaner_id mirrors the LEAD for backward compatibility.';

-- ─── Booking-level crew fields ──────────────────────────────────────────────
ALTER TABLE bookings
  ADD COLUMN IF NOT EXISTS required_crew_size      INT,
  ADD COLUMN IF NOT EXISTS min_crew_size           INT NOT NULL DEFAULT 1,
  ADD COLUMN IF NOT EXISTS target_crew_size        INT,
  -- NULL = solo/legacy (behaves exactly as before). Orthogonal to bookings.status,
  -- like day_status — no change to the booking status machine.
  ADD COLUMN IF NOT EXISTS crew_status             TEXT
    CHECK (crew_status IS NULL OR crew_status IN
      ('NEEDS_STAFFING', 'STAFFING', 'PARTIALLY_STAFFED', 'CONFIRMED',
       'AT_RISK', 'IN_PROGRESS', 'COMPLETED', 'STAFFING_FAILED')),
  ADD COLUMN IF NOT EXISTS crew_assignment_version INT NOT NULL DEFAULT 1,
  -- The customer-elected "add one extra cleaner" upsell (flat fee, priced in
  -- Pricing v2). Distinct from Sweepr's internal capacity-driven crew sizing.
  ADD COLUMN IF NOT EXISTS extra_cleaner_requested BOOLEAN NOT NULL DEFAULT FALSE;

COMMENT ON COLUMN bookings.cleaner_id IS
  'The LEAD cleaner (compatibility pointer). Authoritative crew membership lives in booking_crew_assignments.';
COMMENT ON COLUMN bookings.crew_status IS
  'Crew staffing state, orthogonal to status (like day_status). NULL = solo/legacy booking.';

-- ─── cleaner_relationships: mutual preferred teammate ───────────────────────
CREATE TABLE IF NOT EXISTS cleaner_relationships (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  cleaner_id        UUID NOT NULL REFERENCES cleaners(id) ON DELETE CASCADE,
  other_cleaner_id  UUID NOT NULL REFERENCES cleaners(id) ON DELETE CASCADE,
  relationship      TEXT NOT NULL DEFAULT 'PREFERRED_TEAMMATE'
    CHECK (relationship IN ('PREFERRED_TEAMMATE', 'BLOCKED')),
  -- A request is PENDING until the other cleaner accepts (mutual by acceptance).
  status            TEXT NOT NULL DEFAULT 'PENDING'
    CHECK (status IN ('PENDING', 'ACCEPTED', 'DECLINED')),
  created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CHECK (cleaner_id <> other_cleaner_id),
  UNIQUE (cleaner_id, other_cleaner_id)
);
CREATE INDEX IF NOT EXISTS idx_cleaner_rel_other ON cleaner_relationships (other_cleaner_id, status);

COMMENT ON TABLE cleaner_relationships IS
  'Directed cleaner-to-cleaner preferences. A PREFERRED_TEAMMATE bond is mutual only when an ACCEPTED row exists in both directions; a bonus in crew matching, never an override of eligibility.';

-- ─── crew_peer_ratings: thumbs up/down, only a pair''s FIRST shared booking ──
CREATE TABLE IF NOT EXISTS crew_peer_ratings (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  booking_id        UUID NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,
  rater_cleaner_id  UUID NOT NULL REFERENCES cleaners(id) ON DELETE CASCADE,
  ratee_cleaner_id  UUID NOT NULL REFERENCES cleaners(id) ON DELETE CASCADE,
  thumbs            TEXT NOT NULL CHECK (thumbs IN ('up', 'down')),
  comment           TEXT,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CHECK (rater_cleaner_id <> ratee_cleaner_id),
  -- One rating per ordered pair, ever → prompt/collect ONLY on their first
  -- shared booking (never asked again once they have worked together).
  UNIQUE (rater_cleaner_id, ratee_cleaner_id)
);
CREATE INDEX IF NOT EXISTS idx_crew_peer_ratings_ratee ON crew_peer_ratings (ratee_cleaner_id);

COMMENT ON TABLE crew_peer_ratings IS
  'Cleaner-to-cleaner "would I work with them again" thumbs up/down, collected only on a pair''s first shared booking. Distinct from customer reviews.';

-- ─── Backfill: every existing booking with a cleaner becomes one LEAD seat ──
-- COMPLETED bookings get a COMPLETED seat; everything else an ACCEPTED seat.
-- earnings mirror the booking''s cleaner_payout pool; crew_status stays NULL so
-- these bookings keep behaving as solo/legacy.
INSERT INTO booking_crew_assignments
  (booking_id, cleaner_id, role, seat_index, status, earnings_cents,
   check_in_at, check_out_at, created_at, updated_at)
SELECT
  b.id,
  b.cleaner_id,
  'LEAD',
  0,
  CASE WHEN b.status = 'completed' THEN 'COMPLETED' ELSE 'ACCEPTED' END,
  COALESCE(b.cleaner_payout, 0),
  b.started_at,
  b.completed_at,
  NOW(),
  NOW()
FROM bookings b
WHERE b.cleaner_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM booking_crew_assignments x WHERE x.booking_id = b.id
  );

-- ─── RLS parity (owner-bypass; matches migrations 089/100) ──────────────────
ALTER TABLE booking_crew_assignments ENABLE ROW LEVEL SECURITY;
ALTER TABLE cleaner_relationships    ENABLE ROW LEVEL SECURITY;
ALTER TABLE crew_peer_ratings        ENABLE ROW LEVEL SECURITY;

-- ─────────────────────────────────────────────────────────────────────────
-- 102_team_cleans_compensation.sql
-- ─────────────────────────────────────────────────────────────────────────
/*
 * Copyright © 2026–Present ClearKey Solutions, LLC.
 * All Rights Reserved.
 *
 * Proprietary and Confidential.
 */

-- 102_team_cleans_compensation.sql
-- Team Cleans (multi-cleaner crews) — per-member compensation, tips & ratings.
--
-- Wave 1 foundation (101) added booking_crew_assignments (with per-seat
-- earnings_cents + stripe_transfer_id) and crew_peer_ratings. This migration
-- relaxes the two per-booking UNIQUE constraints that block per-crew-member
-- tips and ratings, so a booking can now carry one tip row and one review row
-- PER cleaner instead of exactly one per booking.
--
-- Payouts stay booking-level (the POOL): payouts.booking_id UNIQUE (mig 052)
-- and payout_ledger's booking-unique index are DELIBERATELY untouched — the
-- per-seat split is tracked on booking_crew_assignments.earnings_cents /
-- stripe_transfer_id (already added in 101), never by fanning out payouts rows.
--
-- Solo bookings are the degenerate crew of one: a single (booking_id, cleaner_id)
-- pair behaves exactly like the old (booking_id) UNIQUE, so solo tips/ratings
-- are unchanged.

-- ─── booking_tips: per-member tips ──────────────────────────────────────────
-- The original inline column UNIQUE (mig 058) is auto-named
-- booking_tips_booking_id_key. Replace it with a composite so each crew member
-- can receive their own split of a customer tip.
ALTER TABLE booking_tips DROP CONSTRAINT IF EXISTS booking_tips_booking_id_key;
DO $$ BEGIN
  ALTER TABLE booking_tips ADD CONSTRAINT booking_tips_booking_cleaner_key UNIQUE (booking_id, cleaner_id);
EXCEPTION WHEN duplicate_object THEN NULL; WHEN duplicate_table THEN NULL;
END $$;

-- ─── reviews: per-member ratings ────────────────────────────────────────────
-- The original inline column UNIQUE (mig 001) is auto-named
-- reviews_booking_id_key. Replace it with a composite so a customer rating can
-- target each cleaner who performed the booking (or the booking overall via the
-- LEAD's cleaner_id).
ALTER TABLE reviews DROP CONSTRAINT IF EXISTS reviews_booking_id_key;
DO $$ BEGIN
  ALTER TABLE reviews ADD CONSTRAINT reviews_booking_cleaner_key UNIQUE (booking_id, cleaner_id);
EXCEPTION WHEN duplicate_object THEN NULL; WHEN duplicate_table THEN NULL;
END $$;

-- Admin/reporting: which cleaners performed a given booking, and each seat's
-- rating. Ratings join booking_crew_assignments on (booking_id, cleaner_id).
CREATE INDEX IF NOT EXISTS idx_reviews_booking ON reviews (booking_id);

-- ─────────────────────────────────────────────────────────────────────────
-- 103_crew_tasks.sql
-- ─────────────────────────────────────────────────────────────────────────
/*
 * Copyright © 2026–Present ClearKey Solutions, LLC.
 * All Rights Reserved.
 *
 * Proprietary and Confidential.
 */

-- 103_crew_tasks.sql
-- Team Cleans — per-booking task decomposition + labor-balanced allocation.
--
-- Wave 1 gave a booking crew SEATS (booking_crew_assignments, mig 101). This
-- migration adds the WORK: a booking's cleaning is decomposed into discrete
-- cleaning_tasks (rooms, extras, whole-home overhead), each with an integer
-- estimated_minutes derived from the Pricing v2 quote engine's per-room labor.
-- A deterministic greedy load-balancer (lib/crew/taskAllocation.ts) then
-- assigns each task to a crew member so LABOR (minutes) is balanced across the
-- crew — not room count — with the LEAD carrying walkthrough/coordination
-- overhead and therefore a lighter cleaning load.
--
-- Gated behind the 'team_task_allocation_enabled' site_setting flag (see
-- lib/crew/crewConfig.ts isTeamFlagEnabled). Solo bookings need no tasks and
-- behave exactly as before.
--
-- NOTE (migration numbering): at authoring time the latest migration on disk
-- was 101_team_cleans.sql; a sibling agent owns 102_*.sql (not yet present).
-- This file is numbered 103 by design to sit after that sibling migration. If
-- 102 is still missing when the consolidated schema is built there will be a
-- numbering gap — that is expected and harmless (build-schema sorts + skips no
-- numbers); it does NOT create 102.

-- ─── cleaning_tasks: one row per decomposed unit of work on a booking ────────
CREATE TABLE IF NOT EXISTS cleaning_tasks (
  id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  booking_id              UUID NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,

  -- Canonical Pricing v2 room type when the task is a room ('kitchen',
  -- 'bathroom', 'bedroom', 'living_room'); NULL for extras / whole-home units.
  room_type               TEXT,
  -- Human-facing label for the work unit ("Kitchen ×1", "Inside Oven", …).
  area_label              TEXT NOT NULL,
  -- The booking's cleaning level for room tasks (refresh / extra_attention /
  -- significant_attention) or the inferred condition band; NULL where N/A.
  cleaning_level          TEXT,

  task_type               TEXT NOT NULL
    CHECK (task_type IN ('room', 'extra', 'operational', 'clutter', 'size')),
  -- Person-minutes of work for this unit, derived from the v2 quote (integer).
  estimated_minutes       INT  NOT NULL,
  -- Whether this unit can be worked concurrently with others (different room /
  -- independent extra). Whole-home overhead (setup, size) is FALSE.
  parallelizable          BOOLEAN NOT NULL DEFAULT TRUE,
  -- A skill/cert a cleaner must hold to take this task (NULL = anyone).
  required_qualification  TEXT,

  -- The crew member currently responsible; NULL while unassigned / dropped.
  assigned_cleaner_id     UUID REFERENCES cleaners(id) ON DELETE SET NULL,
  status                  TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'in_progress', 'complete')),

  created_at              TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at              TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_cleaning_tasks_booking ON cleaning_tasks (booking_id);
CREATE INDEX IF NOT EXISTS idx_cleaning_tasks_booking_status ON cleaning_tasks (booking_id, status);

COMMENT ON TABLE cleaning_tasks IS
  'Per-booking decomposed work units (rooms, extras, whole-home overhead) with integer person-minutes from the Pricing v2 quote. Labor-balanced across the crew by lib/crew/taskAllocation.ts. Only populated for team bookings behind the team_task_allocation_enabled flag.';

-- ─── RLS parity (owner-bypass; matches migrations 100/101) ──────────────────
ALTER TABLE cleaning_tasks ENABLE ROW LEVEL SECURITY;

-- ─────────────────────────────────────────────────────────────────────────
-- 104_seam_connected_accounts.sql
-- ─────────────────────────────────────────────────────────────────────────
-- Copyright © 2026–Present ClearKey Solutions, LLC.
-- Proprietary & Confidential. Internal Use Only.
--
-- 104_seam_connected_accounts.sql
-- Per-customer Seam Connected Accounts + webhook dedup + device isolation.
--
-- BACKGROUND (docs/seam-audit.md §1.2, §1.7#1/#2, §3): the original Smart Entry
-- MVP assumed a SINGLE Seam workspace connection and listed EVERY device in the
-- workspace, attributing them all to whichever customer called /devices/sync —
-- a cross-customer leak. It also had no Connect Webview onboarding, so customer
-- locks were never actually linked and PINs were never provisioned.
--
-- This migration introduces the Seam `connected_account` primitive: a Sweepr
-- user authorizes their smart-lock provider (or Airbnb) through Seam's hosted
-- Connect Webview, which yields a `connected_account` we scope every device
-- lookup to. One canonical `users` row can map to N connected accounts (e.g. a
-- Schlage account AND an Airbnb account).

-- ── Seam connected accounts (one row per user⇄Seam connected_account) ─────────
CREATE TABLE IF NOT EXISTS seam_connected_accounts (
  id                        UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id                   UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  -- The Seam connected_account id. NULL while the Connect Webview is still
  -- pending (authorization not yet completed). Populated on success.
  seam_connected_account_id TEXT,
  -- The Connect Webview we opened for this link — used to poll status and to
  -- correlate the connected_account.* webhook back to this row.
  connect_webview_id        TEXT,
  -- 'seam' = a smart-lock brand link (August/Yale/Schlage/…); 'airbnb' = an
  -- Airbnb link established via Seam (distinct from the .ics calendar sync in
  -- calendar_sources — see routes/smartEntry.ts airbnb endpoints).
  provider                  TEXT NOT NULL DEFAULT 'seam',
  status                    TEXT NOT NULL DEFAULT 'pending'
                              CHECK (status IN ('pending','connected','disconnected','error')),
  created_at                TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at                TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (user_id, seam_connected_account_id)
);
CREATE INDEX IF NOT EXISTS idx_seam_connected_accounts_user
  ON seam_connected_accounts (user_id);
CREATE INDEX IF NOT EXISTS idx_seam_connected_accounts_webview
  ON seam_connected_accounts (connect_webview_id);

COMMENT ON TABLE seam_connected_accounts IS
  'Maps a Sweepr user to their Seam connected_account(s). A pending row holds only the connect_webview_id until the hosted authorization completes; provider distinguishes a smart-lock brand link from an Airbnb link.';

-- ── Seam webhook dedup (idempotency / replay protection) ──────────────────────
-- Seam signs webhooks with Svix; deliveries can be retried/replayed. We claim a
-- dedup row keyed on the Seam event_id (or a hash of the raw body) with
-- INSERT … ON CONFLICT DO NOTHING RETURNING before doing any work — mirrors the
-- stripe_events / yardstik_webhook_events pattern.
CREATE TABLE IF NOT EXISTS seam_webhook_events (
  id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  event_key    TEXT UNIQUE NOT NULL,
  event_type   TEXT,
  resource_id  TEXT,
  received_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_seam_webhook_events_received
  ON seam_webhook_events (received_at);

-- ── Device isolation fix (audit §1.7#2) ──────────────────────────────────────
-- Without a real unique key the /devices/sync `ON CONFLICT DO NOTHING` silently
-- did nothing (no arbiter) and duplicate device rows were possible once more
-- than one lock existed. A device is unique within its connection.
ALTER TABLE smart_lock_devices
  DROP CONSTRAINT IF EXISTS smart_lock_devices_conn_ref_uniq;
DO $$ BEGIN
  ALTER TABLE smart_lock_devices ADD CONSTRAINT smart_lock_devices_conn_ref_uniq UNIQUE (connection_id, provider_device_reference);
EXCEPTION WHEN duplicate_object THEN NULL; WHEN duplicate_table THEN NULL;
END $$;

-- Scope a smart_lock_connections row to one Seam connected_account per customer
-- so we can upsert (customer_id, provider_account_reference) deterministically.
ALTER TABLE smart_lock_connections
  DROP CONSTRAINT IF EXISTS smart_lock_connections_customer_account_uniq;
DO $$ BEGIN
  ALTER TABLE smart_lock_connections ADD CONSTRAINT smart_lock_connections_customer_account_uniq UNIQUE (customer_id, provider_account_reference);
EXCEPTION WHEN duplicate_object THEN NULL; WHEN duplicate_table THEN NULL;
END $$;

-- ── RLS parity (owner-bypass; matches migrations 089/100/101) ────────────────
ALTER TABLE seam_connected_accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE seam_webhook_events     ENABLE ROW LEVEL SECURITY;

-- ─────────────────────────────────────────────────────────────────────────
-- 105_user_reports.sql
-- ─────────────────────────────────────────────────────────────────────────
-- Copyright © 2026–Present ClearKey Solutions, LLC.
-- Proprietary & Confidential. Internal Use Only.
--
-- 105_user_reports.sql
-- Formal user-reporting and investigation system (Trust & Safety).
--
-- Customers and cleaners can formally report the OTHER PARTY on a booking they
-- share (booking-scoped by design: the reporter must be the booking's customer
-- or its assigned cleaner, and the reported user is the counterpart). Reports
-- carry photo evidence stored in the PRIVATE `sweepr-report-objects` R2 bucket
-- (never public; uploads and reads stream through the API, retrieval is
-- admin-only) and are investigated by admins in the /reports console.
--
-- Lifecycle: submitted → under_review → action_taken | dismissed
-- (dismissed may be reopened to under_review; action_taken is terminal).
-- Transitions are enforced app-side in apps/api/src/lib/userReports.ts.

-- ── Reports ──────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS user_reports (
  id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  booking_id         UUID NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,
  -- Canonical users rows for both parties. Denormalized from the booking at
  -- submission time so the report stays intact even if the booking's
  -- assignment later changes.
  reporter_user_id   UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  reported_user_id   UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  reporter_role      TEXT NOT NULL CHECK (reporter_role IN ('customer', 'cleaner')),
  category           TEXT NOT NULL CHECK (category IN (
    'safety_concern', 'property_damage', 'theft', 'harassment',
    'no_show', 'unprofessional_conduct', 'payment_dispute', 'other'
  )),
  description        TEXT NOT NULL,
  status             TEXT NOT NULL DEFAULT 'submitted' CHECK (status IN (
    'submitted', 'under_review', 'action_taken', 'dismissed'
  )),
  -- Resolution fields, set together when an admin closes the investigation.
  resolution_action  TEXT CHECK (resolution_action IS NULL OR resolution_action IN (
    'none', 'warning_issued', 'suspension', 'other'
  )),
  resolution_note    TEXT,
  -- Clerk id of the deciding admin (matches the admin_audit_log actor format).
  resolved_by        TEXT,
  resolved_at        TIMESTAMPTZ,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at         TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_user_reports_booking  ON user_reports (booking_id);
CREATE INDEX IF NOT EXISTS idx_user_reports_reporter ON user_reports (reporter_user_id);
CREATE INDEX IF NOT EXISTS idx_user_reports_reported ON user_reports (reported_user_id);
CREATE INDEX IF NOT EXISTS idx_user_reports_status   ON user_reports (status);
CREATE INDEX IF NOT EXISTS idx_user_reports_created  ON user_reports (created_at DESC);

-- One OPEN report per (booking, reporter) — the duplicate-spam guard. The API
-- pre-checks for a friendly 409, but this index is the race-safe arbiter.
CREATE UNIQUE INDEX IF NOT EXISTS uq_user_reports_open
  ON user_reports (booking_id, reporter_user_id)
  WHERE status IN ('submitted', 'under_review');

COMMENT ON TABLE user_reports IS
  'Formal booking-scoped reports a customer/cleaner files against the counterpart on their booking. Investigated by admins; lifecycle submitted → under_review → action_taken | dismissed.';

-- ── Photo evidence (private bucket: sweepr-report-objects) ───────────────────
CREATE TABLE IF NOT EXISTS user_report_photos (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  report_id     UUID NOT NULL REFERENCES user_reports(id) ON DELETE CASCADE,
  -- Object key inside the sweepr-report-objects bucket (reports/{reportId}/…).
  storage_key   TEXT NOT NULL UNIQUE,
  content_type  TEXT NOT NULL,
  size_bytes    INT  NOT NULL,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_user_report_photos_report ON user_report_photos (report_id);

COMMENT ON TABLE user_report_photos IS
  'Photo evidence attached to a user report. Objects live in the PRIVATE sweepr-report-objects R2 bucket; retrieval streams through the API behind requireAdmin.';

-- ── Investigation notes (admin trail) ────────────────────────────────────────
CREATE TABLE IF NOT EXISTS user_report_notes (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  report_id       UUID NOT NULL REFERENCES user_reports(id) ON DELETE CASCADE,
  -- Clerk id of the admin who wrote the note ('system' rows record automatic
  -- lifecycle events like status transitions for the investigation timeline).
  admin_clerk_id  TEXT NOT NULL,
  note            TEXT NOT NULL,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_user_report_notes_report ON user_report_notes (report_id);

COMMENT ON TABLE user_report_notes IS
  'Admin investigation trail for a user report. Never exposed to the reporter or the reported party.';

-- ── RLS parity (owner-bypass; matches migrations 089/100/101/104) ────────────
ALTER TABLE user_reports       ENABLE ROW LEVEL SECURITY;
ALTER TABLE user_report_photos ENABLE ROW LEVEL SECURITY;
ALTER TABLE user_report_notes  ENABLE ROW LEVEL SECURITY;

-- ─────────────────────────────────────────────────────────────────────────
-- 106_calendar_date_rules.sql
-- ─────────────────────────────────────────────────────────────────────────
-- Copyright © 2026–Present ClearKey Solutions, LLC.
-- Proprietary & Confidential. Internal Use Only.
--
-- 106_calendar_date_rules.sql
-- Admin booking calendar: per-date operational rules (blocks, price
-- adjustments, automatic date coupons), optionally scoped to one service area.
--
-- A rule row applies to exactly ONE calendar date (bulk creation in the admin
-- UI expands ranges/weekday selections into individual rows server-side, so
-- every applied date is a first-class, auditable, individually revocable row).
-- Dates are matched against the CUSTOMER'S LOCAL calendar date of a booking
-- (the date the customer picked in the wizard), not the UTC date of the
-- scheduled instant — see apps/api/src/lib/localDate.ts.
--
-- Scope: service_area_id NULL = platform-wide; set = that service area only
-- (resolved from the booking address's lat/lng against service_areas
-- polygons). Stacking semantics (enforced by uq_calendar_date_rules_scope and
-- apps/api/src/lib/calendarRules.ts):
--   * at most ONE active rule per (date, scope, kind);
--   * for price_adjustment and coupon, an area-specific rule OVERRIDES a
--     platform-wide rule on the same date (they never stack);
--   * for block, platform-wide and area rules union (either one blocks).
--
-- Kinds:
--   * block            — the date accepts no NEW bookings/reschedules. Existing
--                        bookings are untouched; the admin calendar surfaces
--                        them as conflicts for manual action.
--   * price_adjustment — adjustment_type 'percent' (adjustment_value = whole
--                        percent, e.g. 10 = +10%, -15 = 15% off) or 'flat'
--                        (adjustment_value = integer CENTS, negative =
--                        discount). Applied server-side to the pre-tax service
--                        subtotal after any engine minimum, on BOTH the legacy
--                        chain and Pricing v2 (see bookings.ts
--                        computeBookingPricing).
--   * coupon           — an automatic date promotion. The rule carries a
--                        coupon TEMPLATE (coupons are per-user grants in this
--                        codebase, not shared codes — see lib/coupons.ts): on
--                        a matching booking a one-use coupon is minted for the
--                        customer (source 'calendar', source_ref = rule id,
--                        once per customer per rule) and then competes in the
--                        existing best-coupon auto-apply engine, so a better
--                        coupon the customer already holds still wins and the
--                        same coupon can never stack twice.

-- ── Calendar date rules ──────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS calendar_date_rules (
  id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  rule_date        DATE NOT NULL,
  -- NULL = platform-wide; otherwise scoped to one service area.
  service_area_id  UUID REFERENCES service_areas(id) ON DELETE CASCADE,
  kind             TEXT NOT NULL CHECK (kind IN ('block', 'price_adjustment', 'coupon')),
  -- price_adjustment payload (NULL for other kinds).
  adjustment_type  TEXT CHECK (adjustment_type IS NULL OR adjustment_type IN ('percent', 'flat')),
  adjustment_value INTEGER,
  -- coupon template payload (NULL for other kinds). Percent value is 1–100;
  -- amount value is integer cents.
  coupon_kind      TEXT CHECK (coupon_kind IS NULL OR coupon_kind IN ('percent_off', 'amount_off')),
  coupon_value     INTEGER,
  -- Customer-facing label for price_adjustment/coupon rules (shown on the
  -- quote breakdown / availability endpoint); display label for blocks in the
  -- admin UI only. Keep it presentable.
  label            TEXT NOT NULL,
  -- Internal admin note. NEVER sent to customers.
  reason           TEXT,
  active           BOOLEAN NOT NULL DEFAULT TRUE,
  -- Clerk id of the creating admin (matches the admin_audit_log actor format).
  created_by       TEXT,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  -- Each kind carries exactly its own payload.
  CHECK (kind <> 'price_adjustment' OR (
    adjustment_type IS NOT NULL AND adjustment_value IS NOT NULL AND adjustment_value <> 0
    AND coupon_kind IS NULL AND coupon_value IS NULL
  )),
  CHECK (kind <> 'coupon' OR (
    coupon_kind IS NOT NULL AND coupon_value IS NOT NULL AND coupon_value > 0
    AND adjustment_type IS NULL AND adjustment_value IS NULL
  )),
  CHECK (kind <> 'block' OR (
    adjustment_type IS NULL AND adjustment_value IS NULL
    AND coupon_kind IS NULL AND coupon_value IS NULL
  )),
  -- Percent bounds: never below -90% (a bigger discount is a config mistake)
  -- and never above +300%.
  CHECK (adjustment_type IS DISTINCT FROM 'percent' OR (adjustment_value BETWEEN -90 AND 300)),
  CHECK (coupon_kind IS DISTINCT FROM 'percent_off' OR (coupon_value BETWEEN 1 AND 100))
);

-- Stacking guard: at most one ACTIVE rule per (date, scope, kind). NULL scope
-- is folded to the zero uuid so two platform-wide rules of the same kind on
-- the same date conflict (unique indexes treat NULLs as distinct otherwise).
CREATE UNIQUE INDEX IF NOT EXISTS uq_calendar_date_rules_scope
  ON calendar_date_rules (
    rule_date,
    COALESCE(service_area_id, '00000000-0000-0000-0000-000000000000'::uuid),
    kind
  )
  WHERE active;

-- Range queries (admin month grid, availability endpoint, booking checks).
CREATE INDEX IF NOT EXISTS idx_calendar_date_rules_date
  ON calendar_date_rules (rule_date) WHERE active;
CREATE INDEX IF NOT EXISTS idx_calendar_date_rules_area
  ON calendar_date_rules (service_area_id, rule_date) WHERE active;

COMMENT ON TABLE calendar_date_rules IS
  'Admin booking-calendar rules: one row per (date, scope, kind). block stops new bookings/reschedules on that local date; price_adjustment layers a labeled percent/flat operational adjustment onto the server quote; coupon auto-mints a per-customer coupon for bookings on that date. service_area_id NULL = platform-wide.';

-- ── Date-coupon claim lock ───────────────────────────────────────────────────
-- Mirrors migration 088's strict one-claim-per-identity locks for a new coupon
-- source 'calendar' (source_ref = calendar_date_rules.id): each customer can
-- be granted a given date-rule's coupon at most once, race-safe at the DB.
CREATE UNIQUE INDEX IF NOT EXISTS idx_coupons_source_user_once_calendar
  ON coupons (source, source_ref, user_id)
  WHERE user_id IS NOT NULL AND source = 'calendar';

-- ── RLS parity (owner-bypass; matches migrations 089/100/104/105) ────────────
ALTER TABLE calendar_date_rules ENABLE ROW LEVEL SECURITY;

-- ─────────────────────────────────────────────────────────────────────────
-- 107_payout_economics_and_job_type_prefs.sql
-- ─────────────────────────────────────────────────────────────────────────
/*
 * Copyright © 2026–Present ClearKey Solutions, LLC.
 * All Rights Reserved.
 *
 * Proprietary and Confidential.
 */

-- 107_payout_economics_and_job_type_prefs.sql
--
-- Owner-decided payout economics (2026-09) + cleaner job-type preferences:
--   1. Marketplace Services Fee 20% → 30% (standard bookings split 70%
--      cleaner pool / 30% Sweepr; tips stay 100% to cleaner, outside the split).
--   2. Crew pool splits: two-cleaner 54/46 Lead/Support (was 60/40),
--      three-cleaner 36/32/32 (was 40/30/30). Patches any stored crew_config.
--   3. Team Cleans enabled NOW: every team_* flag row seeded to 'true'
--      (the code default is also ON for absent rows; admin can still turn off).
--   4. booking_price_ledger admits 'access_delay_fee' (non-cumulative
--      access-delay/lockout fee, allocated 80% cleaner team / 20% Sweepr at
--      payout — lib/accessDelayFee.ts).
--   5. cleaners.accepted_job_types — canonical job-type preferences over
--      {standard, move_in_out, vacation_rental}. Default = ALL types accepted,
--      so existing cleaners are unaffected (and become eligible for
--      move-in/out + turnover jobs the legacy preferred_service_types default
--      silently excluded them from). Deep Clean is auto-classified within
--      Standard and counts as 'standard' for preference purposes.

-- ─── 1. Marketplace Services Fee → 30% ───────────────────────────────────────
-- Insert a fresh ACTIVE row at 30%, carrying forward every other knob from the
-- most recent active row, then deactivate the superseded rows (history kept).
INSERT INTO platform_fee_settings (
  fee_type, fee_value, minimum_platform_fee, maximum_platform_fee,
  processing_fee_strategy, processing_fee_split_pct, reserve_percentage,
  payout_delay_days, notes
)
SELECT
  'percentage', 30.0000, minimum_platform_fee, maximum_platform_fee,
  processing_fee_strategy, processing_fee_split_pct, reserve_percentage,
  payout_delay_days,
  'Marketplace Services Fee 30% (owner decision 2026-09; standard bookings split 70% cleaner / 30% Sweepr)'
FROM platform_fee_settings
WHERE NOT EXISTS (
  SELECT 1 FROM platform_fee_settings
  WHERE active = TRUE AND fee_type = 'percentage' AND fee_value = 30.0000
)
ORDER BY active DESC, effective_from DESC
LIMIT 1;

UPDATE platform_fee_settings
SET active = FALSE, updated_at = NOW()
WHERE active = TRUE
  AND NOT (fee_type = 'percentage' AND fee_value = 30.0000);

-- ─── 2. Crew pool splits 54/46 and 36/32/32 ──────────────────────────────────
-- The code default (DEFAULT_CREW_CONFIG) already carries the new splits; this
-- patches a stored crew_config row (written by the admin Crew Config page)
-- that would otherwise override with the old 60/40 / 40/30/30 values.
UPDATE site_settings
SET value = jsonb_set(
      jsonb_set(value::jsonb, '{payoutSplitByCrewSize,2}', '[54,46]'::jsonb),
      '{payoutSplitByCrewSize,3}', '[36,32,32]'::jsonb
    )::text,
    updated_at = NOW()
WHERE key = 'crew_config'
  AND value::jsonb ? 'payoutSplitByCrewSize';

-- ─── 3. Team Cleans flags ON ─────────────────────────────────────────────────
INSERT INTO site_settings (key, value) VALUES
  ('team_cleans_enabled', 'true'),
  ('team_auto_crew_sizing_enabled', 'true'),
  ('team_auto_crew_matching_enabled', 'true'),
  ('team_task_allocation_enabled', 'true'),
  ('team_preferred_teammates_enabled', 'true')
ON CONFLICT (key) DO UPDATE SET value = 'true', updated_at = NOW();

-- ─── 4. Ledger event type for access-delay/lockout fees ──────────────────────
ALTER TABLE booking_price_ledger DROP CONSTRAINT IF EXISTS booking_price_ledger_event_type_check;
DO $$ BEGIN
  ALTER TABLE booking_price_ledger ADD CONSTRAINT booking_price_ledger_event_type_check CHECK (event_type IN (
    'initial_quote', 'addon_purchase', 'level_surcharge', 'additional_attention_fee',
    'refusal_fee', 'admin_adjustment', 'tax_adjustment', 'coupon_discount',
    'smart_entry_fee', 'membership_discount', 'quote_refresh', 'access_delay_fee'
  ));
EXCEPTION WHEN duplicate_object THEN NULL; WHEN duplicate_table THEN NULL;
END $$;

-- ─── 5. Cleaner job-type preferences ─────────────────────────────────────────
-- Canonical job types match how the quote engine maps wire service types:
-- move_in_out → move_in_out, vacation_rental → vacation_rental, everything
-- else (standard, deep, recurring, …) → standard. Matching (solo + crew)
-- hard-filters on this column; at least one accepted type is required
-- (enforced by the CHECK and by zod at the API).
ALTER TABLE cleaners
  ADD COLUMN IF NOT EXISTS accepted_job_types TEXT[] NOT NULL
    DEFAULT ARRAY['standard','move_in_out','vacation_rental']::TEXT[];

ALTER TABLE cleaners DROP CONSTRAINT IF EXISTS cleaners_accepted_job_types_check;
DO $$ BEGIN
  ALTER TABLE cleaners ADD CONSTRAINT cleaners_accepted_job_types_check CHECK (
    cardinality(accepted_job_types) >= 1
    AND accepted_job_types <@ ARRAY['standard','move_in_out','vacation_rental']::TEXT[]
  );
EXCEPTION WHEN duplicate_object THEN NULL; WHEN duplicate_table THEN NULL;
END $$;
